const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a polygon spanning a section of the Mississippi River near Memphis, TN.
  // This polygon will serve as our region of interest to calculate water area.
  const geometry = ee.Geometry.Polygon(
    [[[-90.1713, 35.1517],
      [-90.1713, 35.0863],
      [-90.0658, 35.0863],
      [-90.0658, 35.1517]]]);

  const date2021 = { start: '2021-09-01', end: '2021-09-30' };
  const date2023 = { start: '2023-09-01', end: '2023-09-30' };

  // Sentinel-2 cloud masking function using s2cloudless.
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B2', 'B3', 'B4', 'B8', 'B11', 'B12']); // Select relevant bands
  }

  // Function to calculate MNDWI for Sentinel-2
  function addMNDWI(image) {
    // MNDWI = (Green - SWIR1) / (Green + SWIR1)
    // S2 Green = B3, SWIR1 = B11
    return image.addBands(image.normalizedDifference(['B3', 'B11']).rename('MNDWI'));
  }

  // Function to process image collection for a given period
  async function processCollection(datePeriod, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(datePeriod.start, datePeriod.end)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter out images with high cloud cover
      .map(maskS2clouds)
      .map(addMNDWI);

    const initialSize = collection.size().getInfo();

    if (initialSize === 0) {
      console.log(`No images found for ${periodName} after initial filters.`);
      return { totalImages: 0, validPixels: 0, waterArea: null, cloudPct: 100 };
    }

    // Compute median composite
    const medianImage = collection.median();

    // Check if the median image is null (can happen if all images are masked out)
    const hasData = await ee.data.computeImageHistogram({
      image: medianImage.select('B4'), // Check a representative band
      region: geometry,
      scale: 1000,
      maxPixels: 1e9
    }).catch(() => null);

    if (!hasData) {
      console.log(`No valid pixels for ${periodName} after cloud masking.`);
      return { totalImages: initialSize, validPixels: 0, waterArea: null, cloudPct: 100 };
    }

    // Apply MNDWI threshold to classify water (MNDWI > 0)
    const waterMask = medianImage.select('MNDWI').gt(0).rename('water_mask');
    const waterImage = waterMask.updateMask(waterMask); // Mask non-water pixels

    // Calculate valid pixel count for the water mask (using a high-res band like B4 to ensure geometry is covered)
    const countPixels = waterMask.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10, // S2 native resolution
      maxPixels: 1e9
    }).get('water_mask').getInfo();

    if (countPixels === 0) {
      console.log(`No valid water pixels found for ${periodName}.`);
      return { totalImages: initialSize, validPixels: 0, waterArea: null, cloudPct: 100 };
    }

    // Calculate water area (pixel count * pixel area)
    const pixelAreaSqM = 10 * 10; // Sentinel-2 pixel area in square meters
    const waterAreaSqM = countPixels * pixelAreaSqM;
    const waterAreaSqKm = waterAreaSqM / 1e6;

    // Calculate approximate cloud percentage for the composite (assuming masked pixels are clouds/shadows)
    const totalImagePixels = medianImage.select('B4').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10,
      maxPixels: 1e9
    }).get('B4').getInfo();

    let cloudPercentage = 100;
    if (totalImagePixels > 0) {
      const unmaskedPixels = await medianImage.select('B4').updateMask(medianImage.select('B4').mask()).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 10,
        maxPixels: 1e9
      }).get('B4').getInfo();
      cloudPercentage = (1 - (unmaskedPixels / totalImagePixels)) * 100;
    }

    return {
      totalImages: initialSize,
      validPixels: countPixels,
      waterArea: waterAreaSqKm,
      cloudPct: cloudPercentage
    };
  }

  console.log('Analyzing September 2021...');
  const result2021 = await processCollection(date2021, 'September 2021');
  console.log(`2021 Images: ${result2021.totalImages}`);
  console.log(`2021 Valid Water Pixels: ${result2021.validPixels} (Cloud%: ${result2021.cloudPct.toFixed(1)}%)`);
  console.log(`2021 Water Area: ${result2021.waterArea !== null ? result2021.waterArea.toFixed(2) + ' sq km' : 'N/A'}`);

  console.log('\nAnalyzing September 2023...');
  const result2023 = await processCollection(date2023, 'September 2023');
  console.log(`2023 Images: ${result2023.totalImages}`);
  console.log(`2023 Valid Water Pixels: ${result2023.validPixels} (Cloud%: ${result2023.cloudPct.toFixed(1)}%)`);
  console.log(`2023 Water Area: ${result2023.waterArea !== null ? result2023.waterArea.toFixed(2) + ' sq km' : 'N/A'}`);

  // 5. Validation & Final Answer
  if (result2021.totalImages === 0 || result2023.totalImages === 0) {
    console.log("C1"); // Empty Collection
    return;
  }

  if (result2021.validPixels === 0 || result2023.validPixels === 0) {
    console.log("C2"); // No Valid Pixels after masking
    return;
  }

  if (result2021.waterArea === null || result2023.waterArea === null || isNaN(result2021.waterArea) || isNaN(result2023.waterArea)) {
    console.log("C3"); // Calculation Failure (e.g., NaN or null result)
    return;
  }

  const area2021 = result2021.waterArea;
  const area2023 = result2023.waterArea;

  if (area2023 < area2021) {
    console.log("A"); // Yes, width (proxied by area) decreased.
  } else {
    console.log("B"); // No, width (proxied by area) did not decrease.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
